parameters.jsCode:
// Car OS Media - brief normaliser and campaign playbook resolver.
// Turns the Telegram brief into a full production spec: render sizes for both
// models, beat count, cost estimate, and the creative archetype the agents follow.

const brief = $("Creative Brief").first().json.data || {};
const cfg = $("Car OS Config").first().json || {};
const chatId = String($("Car OS Trigger").first().json.message.chat.id);
const sourceUrl = $("Host Source Image").first().json.data.url;
// ImgBB hands back a one-click delete page with every upload. The upload also carries
// an expiration so it removes itself, but a campaign can be cancelled long before that
// and a customer photo with a readable plate on a public host is not something to leave
// lying around. Carry the link so the operator can pull it immediately.
const sourceDeleteUrl = String(
  ($("Host Source Image").first().json.data || {}).delete_url || ""
);

// Editing a sendAndWait node in the n8n UI strips the explicit fieldName from its
// form fields, after which the answer keys are derived from the labels instead.
// pick() resolves either shape by normalising both sides, so the brief keeps
// working whichever way the node was last saved.
function pick(src, key, label) {
  const norm = function (s) { return String(s).toLowerCase().replace(/[^a-z0-9]/g, ""); };
  const map = {};
  for (const k of Object.keys(src)) { map[norm(k)] = src[k]; }
  const byKey = map[norm(key)];
  if (byKey !== undefined && byKey !== "") { return byKey; }
  const byLabel = map[norm(label)];
  if (byLabel !== undefined && byLabel !== "") { return byLabel; }
  return "";
}

const carModel   = pick(brief, "car_model",   "Vehicle / model");
const objective  = pick(brief, "objective",   "Campaign objective") || "Transformation and Detailing Reveal";
const ratioRaw   = pick(brief, "ratio",       "Aspect ratio") || "9:16";
const filmLength = pick(brief, "film_length", "Film length");
const tone       = pick(brief, "tone",        "Brand voice") || "Premium and Cinematic";
const brandName  = pick(brief, "brand_name",  "Brand / garage name (optional)");
const ctaValue   = pick(brief, "cta",         "Call to action (optional)");
const language   = pick(brief, "language",    "Caption language") || "English";

const RATIOS = {
  "9:16": { label: "9:16", image: { width: 1024, height: 1536 }, video: { width: 720, height: 1280 }, placement: "Reels / TikTok / Shorts" },
  "4:5":  { label: "4:5",  image: { width: 1024, height: 1536 }, video: { width: 1024, height: 1280 }, placement: "Feed portrait" },
  "1:1":  { label: "1:1",  image: { width: 1024, height: 1024 }, video: { width: 960, height: 960 },  placement: "Feed square" },
  "16:9": { label: "16:9", image: { width: 1536, height: 1024 }, video: { width: 1280, height: 720 },  placement: "YouTube / landscape" }
};

// ---- THE CAMPAIGN PLAYBOOK ----------------------------------------------
// Eight automotive archetypes. Copy an entry to add your own, then add the
// same label to the objective dropdown in the Creative Brief node.
const PLAYBOOK = {
  "Transformation and Detailing Reveal": {
    archetype: "Transformation Reveal",
    audience: "Detailing clients, owners of neglected performance cars, car-care obsessives who binge satisfying restoration content.",
    visual_language: "Bright premium detailing bay, wet floor reflections, foam texture, macro paint defects, controlled softbox light, high-clarity clearcoat highlights.",
