    beat_arc: ["Arrival on the forecourt, full-car stance established", "Value details: wheels, interior, trim, condition", "Key handover energy and closing hero shot"],
    audio_bed: "Upbeat commercial bed, door thunk, key jingle, satisfying close accents.",
