    motion_language: "Frost-to-clear transitions, water beading in macro, tyre swap sequence, breath-fog atmosphere, protective coating sweep, clean drive-off.",
    beat_arc: ["Frozen, salted, neglected winter state", "Protection applied: coating, tyres, glass treatment", "Confident cold-weather drive-off, water beading off paint"],
    audio_bed: "Wind, frost crackle, impact wrench, water beading, warm resolving music bed.",
    hook_formula: "Name the seasonal risk, then remove it.",
    cta_style: "Booking-driven",
    negatives: "summer light, dry tarmac, tropical setting"
