const BEATS = { "Teaser 1 beat 5s": 1, "Standard 2 beats 10s": 2, "Signature 3 beats 15s": 3 };

const ratioKey = String(ratioRaw).split(" ")[0];
const ratio = RATIOS[ratioKey] || RATIOS["9:16"];
const play = PLAYBOOK[objective] || PLAYBOOK["Transformation and Detailing Reveal"];
const beats = BEATS[filmLength] || 3;
const framesPerBeat = 121;

// Unit prices live in Car OS Config, not here, so a fal price change is one edit in
