const PRICE_FRAME  = Number(cfg.price_frame_usd) || 0.09;
const PRICE_VIDEO  = Number(cfg.price_video_per_mp_usd) || 0.0024075;
const PRICE_STITCH = Number(cfg.price_stitch_usd) || 0.02;
