## Vehicle
{{ $json.car_model }}. Analyse the attached photograph only. Do not invent trim, specs or model year.
The car in that photograph is the one that will be rendered, so read it precisely before you brief anyone.

## Assignment
Objective: {{ $json.objective }}
Archetype: {{ $json.archetype }}
Audience: {{ $json.audience }}
Brand voice: {{ $json.tone }}
Brand or garage: {{ $json.brand_name }}
Call to action: {{ $json.cta }}
Caption language: {{ $json.language }}

## Format lock
Aspect ratio: {{ $json.ratio }} ({{ $json.placement }})
Beats required: {{ $json.beats }}
Seconds per beat: {{ $json.seconds_per_beat }}, total {{ $json.total_seconds }}s
Frame render size: {{ $json.image_width }}x{{ $json.image_height }}
Video render size: {{ $json.video_width }}x{{ $json.video_height }} at 24fps

## Playbook direction. Follow this, do not substitute another archetype.
Visual language: {{ $json.visual_language }}
Motion language: {{ $json.motion_language }}
Audio bed: {{ $json.audio_bed }}
Hook formula: {{ $json.hook_formula }}
CTA style: {{ $json.cta_style }}

## Beat arc. One frame prompt and one video prompt per entry, in this order.
{{ $json.beat_arc_text }}

## Deliver
Run the crew in order: Brand Strategist, then Automotive Art Director, then Cinematic Motion
Director, then Social Copy Chief. Hand each crew member every previous output so the campaign
stays coherent. Return exactly {{ $json.beats }} entries in frame_prompts, video_prompts and audio_notes.
Return identity_lock exactly as the Art Director wrote it. It is copied word for word into every
image request and into every correction pass, and it is the only thing keeping the vehicle from
drifting, so it must describe the car in the photograph and nothing else.

parameters.jsCode:
// Flatten the Creative Director output onto the production spec, and pad or trim
// every array to exactly the beat count the brief paid for.

const spec = $("Car OS Brief Compiler").first().json;
const out = $input.first().json.output || $input.first().json;
const n = spec.beats;

// The Copy Chief sometimes double-escapes newlines in its JSON, which publishes as a
// literal backslash n instead of a line break. Turn those back into real newlines.
// Only backslash sequences are rewritten, so a URL like https://example.com is
// never touched.
function nl(s) {
  return String(s == null ? "" : s)
    .replace(/\\r\\n/g, "\n")
    .replace(/\\n/g, "\n")
    .replace(/\\r/g, "\n")
    .replace(/\\t/g, " ")
    .replace(/\r\n/g, "\n")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

function take(arr, fallback) {
  const list = Array.isArray(arr) ? arr : [];
  const filled = [];
  for (let i = 0; i < n; i++) {
    filled.push(nl(list[i] || list[list.length - 1] || fallback));
  }
  return filled;
}

// Telegram sendAndWait panels are parsed as legacy Markdown and offer no parse_mode
// override, so any asterisk, underscore, backtick or bracket in LLM prose breaks the
// entire message. Keep the raw text for captions and the data tables, and expose
// sanitised _md twins for anything rendered in a panel.
function md(s) {
  return String(s == null ? "" : s).replace(/[*_`\[\]()]/g, " ").replace(/[ \t]+/g, " ").trim();
}

const merged = Object.assign({}, spec);
merged.campaign_name = nl(out.campaign_name) || (spec.car_model + " " + spec.archetype);
merged.brand_angle = nl(out.brand_angle);
merged.audience_insight = nl(out.audience_insight);
merged.hook = nl(out.hook);
merged.cta_final = nl(out.cta) || spec.cta || "";
merged.art_direction_note = nl(out.art_direction_note);

// identity_lock is prepended verbatim to every image request and every correction pass,
// so it is the one field that must never be empty. If the Art Director skipped it, fall
// back to a statement that points at the photograph rather than inventing a description
// of a car this node cannot see.
merged.identity_lock = nl(out.identity_lock) ||
  ("the vehicle exactly as it appears in the source photograph, including its paint colour and " +
   "finish, wheel design, badges, body shape, ride height and every existing mark on it");

merged.frame_prompts = take(out.frame_prompts, spec.visual_language);
merged.video_prompts = take(out.video_prompts, spec.motion_language);
merged.audio_notes = take(out.audio_notes, spec.audio_bed);
merged.caption_instagram = nl(out.caption_instagram);
merged.caption_tiktok = nl(out.caption_tiktok);
merged.caption_youtube = nl(out.caption_youtube);
merged.caption_facebook = nl(out.caption_facebook);
merged.caption_linkedin = nl(out.caption_linkedin);
merged.caption_x = nl(out.caption_x);
merged.youtube_title = nl(out.youtube_title) || (spec.car_model + " " + spec.archetype);
merged.hashtags = nl(out.hashtags);
merged.first_comment = nl(out.first_comment);
merged.status = "blueprint_ready";

merged.campaign_name_md = md(merged.campaign_name);
merged.hook_md = md(merged.hook);
merged.brand_angle_md = md(merged.brand_angle);
merged.audience_insight_md = md(merged.audience_insight);
merged.art_direction_note_md = md(merged.art_direction_note);
merged.archetype_md = md(merged.archetype);
merged.identity_lock_md = md(merged.identity_lock);

return [{ json: merged }];

