parameters.jsCode:
// One item per beat. The steer note arrives on $json from whichever path ran:
// Set: No Steer when the operator approved as-is, or Capture Adjustments when they
// tapped Adjust and filled the follow-up form.
const bp = $("Set Campaign Blueprint").first().json;
const steerIn = $input.first().json || {};
const steer = String(steerIn.visual_note || "").trim();
const hook = String(steerIn.hook_override || "").trim() || bp.hook;

// openai/gpt-image-2/edit exposes no input_fidelity, reference-strength or identity
// setting. The prompt is the only thing holding the car still, so the lock LEADS every
// request rather than trailing it, and it is repeated word for word on every beat and
// every refine pass: a consistent block reads as one standing instruction, whereas a
// paraphrased one reads as a new instruction and invites the model to reinterpret.
const archetype = String(bp.archetype || "");
const finishMayChange = /wrap|custom|repaint|colour change|color change/i.test(archetype);

const paintClause = finishMayChange
  ? "FINISH: this archetype changes the finish. Colour and finish may change exactly as the " +
    "scene below describes, and only where it describes. Every other clause in this lock still " +
    "applies without exception."
  : "FINISH: paint colour, finish and gloss level stay exactly as photographed. Dirt, foam, " +
    "water, polish and reflections may sit on top of the paint, but the paint underneath is the " +
    "same colour it was.";

const lock =
  "=== SUBJECT LOCK. HIGHEST PRIORITY. OVERRIDES EVERYTHING BELOW. ===\n" +
  "This is an edit of the attached photograph, not a new image. The vehicle in that photograph " +
  "is the subject and must survive the edit unchanged.\n\n" +
  "THE CAR, AS PHOTOGRAPHED: " + bp.identity_lock + "\n\n" +
  "REPRODUCE EXACTLY, WITH ZERO DEVIATION: body shape and proportions; roofline and greenhouse; " +
  "every panel crease, shut line and vent; front and rear bumper design; grille shape and mesh " +
  "pattern; headlight and daytime running light signature; tail-light signature; mirror shape and " +
  "mounting; wheel design including spoke count, spoke shape and wheel finish; tyre profile; brake " +
  "caliper colour; ride height and stance; and every aftermarket, aero, worn or damaged part " +
  "already present on the car.\n\n" +
  "NEVER: substitute a different make, model, generation, trim or body style; add or remove doors, " +
  "wheels, spoilers, vents, lights, badges or exhaust tips; straighten, widen, lower or otherwise " +
  "stylise the bodywork; or rotate the car to an angle the scene did not ask for.\n\n" +
  paintClause;

// The old prompt banned every letter and number in the image while also demanding the badge
// be preserved, which is a contradiction the model resolves by guessing. Separate the two:
// added graphics are banned, the car's own markings are protected.
const renderRules =
  "=== RENDERING ===\n" +
  "Photographic, not illustrated and not CGI. Aspect ratio " + bp.ratio + ".\n" +
  "Add no graphics of any kind: no captions, subtitles, watermarks, invented logos, UI, borders " +
  "or frames.\n" +
  "The car's own factory badges, emblems and number plate are part of its identity. Keep them " +
  "exactly as photographed. Do not re-letter, restyle, blur or remove them.";

const items = [];
for (let i = 0; i < bp.beats; i++) {
  let scene = "=== SCENE. Beat " + (i + 1) + " of " + bp.beats + ". ===\n" + bp.frame_prompts[i];
  if (steer) {
    scene = scene + "\n\nOPERATOR DIRECTION, apply strictly, but never at the expense of the " +
      "subject lock above: " + steer;
  }

  items.push({
    json: {
      session_id: bp.session_id,
      chat_id: bp.chat_id,
      campaign_name: bp.campaign_name,
      hook: hook,
      beat: i + 1,
      beat_label: "Beat " + (i + 1) + " of " + bp.beats,
      beat_brief: bp.beat_arc[i],
      scene_prompt: bp.frame_prompts[i],
      identity_lock: bp.identity_lock,
      image_prompt: lock + "\n\n" + scene + "\n\n" + renderRules,
      video_prompt: bp.video_prompts[i],
      audio_note: bp.audio_notes[i],
      source_image_url: bp.source_image_url,
      image_width: bp.image_width,
      image_height: bp.image_height,
      image_quality: bp.image_quality,
      video_width: bp.video_width,
      video_height: bp.video_height,
      num_frames: bp.frames_per_beat,
      negative_prompt: bp.negative_prompt
    }
  });
}
return items;

// Normalises the frame set coming from either the first pass or a refinement pass,
// so the review gate and the motion lane always read the same shape.

const bp = $("Set Campaign Blueprint").first().json;
const rows = ($input.first().json.data || []).filter(function (r) { return r && r.frame_url; });
rows.sort(function (a, b) { return a.beat - b.beat; });

const urls = [];
for (const r of rows) { urls.push(r.frame_url); }

return [{
  json: {
    session_id: bp.session_id,
    chat_id: bp.chat_id,
    campaign_name: bp.campaign_name,
    campaign_name_md: bp.campaign_name_md || bp.campaign_name,
    beats: rows.length,
    ratio: bp.ratio,
    total_seconds: rows.length * 5,
    revision: $runIndex,
    frames: rows,
    frame_urls: urls.join(" | ")
  }
}];

// Fan the approved frame set out into one LTX render job per beat.

const bp = $("Set Campaign Blueprint").first().json;
const set = $("Compile Frame Set").last().json;

const items = [];
for (const f of set.frames) {
  items.push({
    json: {
      session_id: bp.session_id,
      chat_id: bp.chat_id,
      campaign_name: bp.campaign_name,
      beat: f.beat,
      beat_label: f.beat_label,
      frame_url: f.frame_url,
      video_prompt: f.video_prompt,
      audio_note: f.audio_note,
      video_width: f.video_width || bp.video_width,
      video_height: f.video_height || bp.video_height,
      num_frames: f.num_frames || bp.frames_per_beat,
      negative_prompt: f.negative_prompt || bp.negative_prompt
    }
  });
}
return items;

// The compose endpoint returns the finished file under video_url, but fal has used
// both shapes. Accept either, and fail loudly rather than publishing nothing.

const bp = $("Set Campaign Blueprint").first().json;
const r = $input.first().json;
const url = r.video_url || (r.video && r.video.url) || null;

if (!url) {
  throw new Error("Stitch finished but no video URL was returned: " + JSON.stringify(r).slice(0, 400));
}

return [{
  json: {
    session_id: bp.session_id,
    chat_id: bp.chat_id,
    campaign_name: bp.campaign_name,
    campaign_name_md: bp.campaign_name_md || bp.campaign_name,
    hook: bp.hook,
    hook_md: bp.hook_md || bp.hook,
    ratio: bp.ratio,
    total_seconds: $("Compile Frame Set").last().json.total_seconds,
    est_cost_usd: bp.est_cost_usd,
    film_url: url,
    caption_instagram: bp.caption_instagram,
    caption_tiktok: bp.caption_tiktok,
    caption_youtube: bp.caption_youtube,
    caption_facebook: bp.caption_facebook,
    caption_linkedin: bp.caption_linkedin,
    caption_x: bp.caption_x,
    youtube_title: bp.youtube_title,
    hashtags: bp.hashtags,
    first_comment: bp.first_comment,
    brand_link: bp.brand_link
  }
}];

// Iterative editing. Each targeted frame is re-edited from the CURRENT frame, with the
// original photograph supplied as a second image so the vehicle identity cannot drift.
// Beats outside the operator focus pass through untouched and cost nothing.
const bp = $("Set Campaign Blueprint").first().json;
const current = $("Compile Frame Set").last().json;
const ask = $("Capture Frame Notes").last().json || {};
const notes = String(ask.refine_notes || "").trim();
const focus = ask.beat_focus || "All beats";
const focusBeat = focus === "All beats" ? 0 : parseInt(String(focus).replace(/[^0-9]/g, ""), 10);

// The same subject lock as Build Beat Plan, word for word. A correction pass is where
// identity drift actually happens, because the model is now editing an edit rather than
// the photograph, so the lock has to be at least as loud here as it was on pass one.
const finishMayChange = /wrap|custom|repaint|colour change|color change/i.test(String(bp.archetype || ""));

const paintClause = finishMayChange
  ? "FINISH: this archetype changes the finish. Colour and finish may change exactly as the " +
    "correction below describes, and only where it describes. Every other clause in this lock " +
    "still applies without exception."
  : "FINISH: paint colour, finish and gloss level stay exactly as photographed. Dirt, foam, " +
    "water, polish and reflections may sit on top of the paint, but the paint underneath is the " +
    "same colour it was.";

const lock =
  "=== SUBJECT LOCK. HIGHEST PRIORITY. OVERRIDES EVERYTHING BELOW. ===\n" +
  "Two images are attached. IMAGE 1 is the frame being corrected. IMAGE 2 is the original " +
  "photograph of the car and is the identity reference. Where the two disagree about the " +
  "vehicle, IMAGE 2 is correct.\n\n" +
  "THE CAR, AS PHOTOGRAPHED: " + bp.identity_lock + "\n\n" +
  "REPRODUCE EXACTLY, WITH ZERO DEVIATION: body shape and proportions; roofline and greenhouse; " +
  "every panel crease, shut line and vent; front and rear bumper design; grille shape and mesh " +
  "pattern; headlight and daytime running light signature; tail-light signature; mirror shape and " +
  "mounting; wheel design including spoke count, spoke shape and wheel finish; tyre profile; brake " +
  "caliper colour; ride height and stance; and every aftermarket, aero, worn or damaged part " +
  "already present on the car.\n\n" +
  "NEVER: substitute a different make, model, generation, trim or body style; add or remove doors, " +
  "wheels, spoilers, vents, lights, badges or exhaust tips; straighten, widen, lower or otherwise " +
  "stylise the bodywork; or rotate the car to a new angle.\n\n" +
  paintClause;

const renderRules =
  "=== RENDERING ===\n" +
  "Photographic, not illustrated and not CGI. Aspect ratio " + bp.ratio + ".\n" +
  "Add no graphics of any kind: no captions, subtitles, watermarks, invented logos, UI, borders " +
  "or frames.\n" +
  "The car's own factory badges, emblems and number plate are part of its identity. Keep them " +
  "exactly as photographed. Do not re-letter, restyle, blur or remove them.";

const items = [];
for (const f of current.frames) {
  const targeted = focusBeat === 0 || focusBeat === f.beat;

  // A correction changes one thing. Everything the operator did not mention is held still
  // explicitly, otherwise the model treats the whole frame as up for renegotiation.
  const correction =
    "=== CORRECTION ===\n" +
    "Apply only this correction: " + notes + "\n\n" +
    "Everything else in IMAGE 1 stays exactly as it is: lighting setup and direction, location, " +
    "time of day, camera angle, camera height, focal length, framing, composition, colour grade, " +
    "and the stage of the transformation this beat is at. Do not re-stage the shot.";

  const prompt = notes
    ? lock + "\n\n" + correction + "\n\n" + renderRules
    : f.image_prompt;

  const row = Object.assign({}, f);
  row.needs_refine = targeted && notes.length > 0;
  row.refine_prompt = prompt;
  row.identity_anchor_url = bp.source_image_url;
  row.identity_lock = bp.identity_lock;
  row.image_width = bp.image_width;
  row.image_height = bp.image_height;
  row.image_quality = bp.image_quality;
  items.push({ json: row });
}
return items;

// Carry the beat forward with the newly refined URL.

const src = $("Loop Refinements").first().json;
const res = $input.first().json;
const newUrl = res && res.images && res.images[0] ? res.images[0].url : null;

const row = Object.assign({}, src);
row.frame_url = newUrl || src.frame_url;
return [{ json: row }];

// Postoria returns one item per connected account, and the network key punctuation
// varies: x, linked_in, google_business_profile. Key the roster on a normalised
// form so the console selection matches whatever style Postoria uses, and keep the
// original label for display and logging.
//
// roster_summary is rendered inside a Telegram Markdown message, and a key like
// linked_in would open an unclosed italic entity and make Telegram reject the whole
// message, so strip the Markdown control characters from anything shown.
function norm(s) {
  return String(s == null ? "" : s).toLowerCase().replace(/[^a-z0-9]/g, "");
}
function md(s) {
  return String(s == null ? "" : s).replace(/[*_`\[\]()]/g, " ").replace(/[ \t]+/g, " ").trim();
}

const roster = {};
const labelFor = {};
const lines = [];

for (const item of $input.all()) {
  const a = item.json || {};
  const raw = String(a.network || a.platform || a.provider || a.type || "");
  const key = norm(raw);
  const id = a.id != null ? a.id : (a.account_id != null ? a.account_id : a._id);
  if (!key || id == null) { continue; }
  if (!roster[key]) { roster[key] = []; labelFor[key] = raw; }
  roster[key].push(String(id));
  lines.push(md(raw) + ": " + md(a.name || a.username || a.handle || id));
}

const keys = Object.keys(roster);

return [{
  json: {
    roster: roster,
    label_for: labelFor,
    connected_networks: keys,
    account_count: keys.length,
    roster_summary: lines.length ? lines.join("\n") : "No social accounts are connected in Postoria yet."
  }
}];

