parameters.jsCode:
// Guarded: this node is the last thing standing between an approved campaign and a
// live post, so any throw is re-raised with a label instead of a bare stack trace.
try {

// Map the chosen networks onto real Postoria account IDs, pick the platform-native
// caption, fit it to the strictest character limit in the selection, and resolve the
// schedule to an unambiguous instant.
//
// n8n keys sendAndWait form answers by the field LABEL, not fieldName. pick()
// resolves either shape.
function pick(src, key, label) {
  const n = function (s) { return String(s).toLowerCase().replace(/[^a-z0-9]/g, ""); };
  const map = {};
  for (const k of Object.keys(src)) { map[n(k)] = src[k]; }
  const byKey = map[n(key)];
  if (byKey !== undefined && byKey !== "") { return byKey; }
  const byLabel = map[n(label)];
  if (byLabel !== undefined && byLabel !== "") { return byLabel; }
  return "";
}

// Postoria network keys carry varying punctuation (linked_in, google_business_profile).
// Normalise both the roster keys and the operator selection so they always meet.
function norm(s) {
  return String(s == null ? "" : s).toLowerCase().replace(/[^a-z0-9]/g, "");
}

// Hard caps enforced by each network. Postoria rejects the whole post if the caption
// exceeds the limit of ANY selected account, so the strictest one wins.
const LIMITS = {
  x: 280,
  bluesky: 300,
  threads: 500,
  pinterest: 500,
  googlebusinessprofile: 1500,
  tiktok: 2200,
  instagram: 2200,
  linkedin: 3000,
  tumblr: 4096,
  youtube: 5000,
  facebook: 63206
};
const NO_LIMIT = 100000;

// Networks with no still-image post type. Sending one an image makes Postoria reject
// the entire batch, so drop them from a still post and report it instead.
const NO_IMAGE = { youtube: true };

// Networks with no video post type. Google Business Profile publishes photos and text
// through its API but it cannot take video, so a finished film must never be routed
// there. Same failure mode as a still on YouTube: Postoria rejects the whole batch.
const NO_VIDEO = { googlebusinessprofile: true };

function fit(text, limit) {
  const base = String(text || "").trim();
  if (base.length <= limit) { return base; }
  let cut = base.slice(0, limit - 1);
  const sp = cut.lastIndexOf(" ");
  if (sp > limit * 0.6) { cut = cut.slice(0, sp); }
  return cut.trim() + "…";
}

// ---- schedule resolution ---------------------------------------------------
// Postoria rejects the whole post if scheduled_time is not in the future, and it does
// so only after the media has been uploaded. Resolve and check the moment here, in the
// workflow timezone, so a mistyped date is caught with an explanation instead of a bare
// validation_failed coming back from the API.
function parseDay(s, zone) {
  const t = String(s || "").trim().replace(/[\/.]/g, "-");
  let m = t.match(/(\d{4})-(\d{1,2})-(\d{1,2})/);
  if (m) {
    return DateTime.fromObject(
      { year: Number(m[1]), month: Number(m[2]), day: Number(m[3]) }, { zone: zone });
  }
  // Day-first, the order most locales type by hand.
  m = t.match(/(\d{1,2})-(\d{1,2})-(\d{4})/);
  if (m) {
    return DateTime.fromObject(
      { year: Number(m[3]), month: Number(m[2]), day: Number(m[1]) }, { zone: zone });
  }
  return null;
}

function parseClock(s) {
  const t = String(s || "").trim().toLowerCase();
  if (!t) { return null; }
  const pm = t.indexOf("pm") !== -1;
  const am = t.indexOf("am") !== -1;
  const digits = t.replace(/[^0-9:]/g, "");
  let h = null;
  let mi = 0;
  if (digits.indexOf(":") !== -1) {
    const parts = digits.split(":");
    h = parseInt(parts[0], 10);
    mi = parseInt(parts[1] || "0", 10);
  } else if (digits.length === 4) {
    h = parseInt(digits.slice(0, 2), 10);
    mi = parseInt(digits.slice(2), 10);
  } else if (digits.length === 1 || digits.length === 2) {
    h = parseInt(digits, 10);
  }
  if (h === null || isNaN(h) || isNaN(mi)) { return null; }
  if (pm && h < 12) { h = h + 12; }
  if (am && h === 12) { h = 0; }
  if (h < 0 || h > 23 || mi < 0 || mi > 59) { return null; }
  return { h: h, m: mi };
}

const film = $("Set Publish Payload").first().json;
const isImage = film.media_kind === "image";
const rosterNode = $("Build Account Roster").first().json;
const roster = rosterNode.roster || {};
const labelFor = rosterNode.label_for || {};
const form = $("Publish Console").first().json.data || {};
const media = $input.first().json;

const mediaId = media.id != null ? media.id : (media.media_id != null ? media.media_id : media.file_id);
if (mediaId == null) {
  throw new Error("Postoria did not return a media ID: " + JSON.stringify(media).slice(0, 300));
}

const rawSelection = String(pick(form, "networks", "Publish to")).split(",");
const selected = [];
let wantsAll = false;
for (const raw of rawSelection) {
  const k = norm(raw);
  if (!k) { continue; }
  if (k.indexOf("allconnected") !== -1) { wantsAll = true; continue; }
  selected.push(k);
}

// All connected means whatever the workspace has right now, so an account added in
// the Postoria dashboard is picked up with no change to this workflow.
const chosenRaw = wantsAll ? Object.keys(roster) : selected;

const chosen = [];
const skipped = [];
for (const net of chosenRaw) {
  const label = labelFor[net] || net;
  if (isImage && NO_IMAGE[net]) { skipped.push(label + " (no image post type)"); continue; }
  if (!isImage && NO_VIDEO[net]) { skipped.push(label + " (no video post type)"); continue; }
  chosen.push(net);
}

const accountIds = [];
const matched = [];
const missing = [];
for (const net of chosen) {
  if (roster[net] && roster[net].length) {
    for (const id of roster[net]) { accountIds.push(id); }
    matched.push(net);
  } else {
    missing.push(net);
  }
}

if (!accountIds.length) {
  const why = skipped.length
    ? " Dropped because this asset has no post type there: " + skipped.join(", ") + "."
    : "";
  throw new Error("Nothing left to publish to. Selected: " + chosenRaw.join(", ") + "." + why + " Connected in Postoria: " + Object.keys(roster).join(", "));
}

const modeLabel = pick(form, "publish_mode", "When") || "Publish now";
const modeRaw = String(modeLabel).toLowerCase();
let publishMode = "publish_now";
if (modeRaw.indexOf("schedule") !== -1) { publishMode = "schedule"; }

const zone = $now.zoneName;
let scheduledTime = "";
let scheduleHuman = "";
let scheduleError = null;

if (publishMode === "schedule") {
  let dayRaw = String(pick(form, "schedule_date", "Schedule date")).trim();
  let timeRaw = String(pick(form, "schedule_time", "Schedule time (24h)")).trim();

  // A console submitted before the field was split sends one combined string.
  const legacy = String(pick(form, "scheduled_time", "Schedule for (used only when Schedule is selected)")).trim();
  if (!dayRaw && legacy) {
    dayRaw = legacy;
    const lm = legacy.match(/(\d{1,2}:\d{2})/);
    if (!timeRaw && lm) { timeRaw = lm[1]; }
  }

  if (!dayRaw) {
    // Nothing given at all. Two hours out was the old default and stays the default.
    const when = $now.plus({ hours: 2 });
    scheduledTime = when.toISO();
    scheduleHuman = when.toFormat("cccc d LLLL yyyy 'at' HH:mm");
  } else {
    const day = parseDay(dayRaw, zone);
    const clock = parseClock(timeRaw || "09:00");
    if (!day || !day.isValid) {
      scheduleError = {
        code: "schedule_unreadable",
        param: "scheduled_time",
        message: "I could not read \"" + dayRaw + "\" as a date. Use the date picker, or type " +
          "it as YYYY-MM-DD, for example " + $now.plus({ days: 1 }).toFormat("yyyy-MM-dd") + "."
      };
    } else if (!clock) {
      scheduleError = {
        code: "schedule_unreadable",
        param: "scheduled_time",
        message: "I could not read \"" + timeRaw + "\" as a time. Use 24-hour HH:mm, for example 18:30."
      };
    } else {
      const when = day.set({ hour: clock.h, minute: clock.m, second: 0, millisecond: 0 });
      if (when <= $now.plus({ minutes: 1 })) {
        // A schedule in the past is nearly always the day and the month the wrong way
        // round, so offer the swap rather than only refusing.
        const swapped = DateTime.fromObject(
          { year: when.year, month: when.day, day: when.month, hour: when.hour, minute: when.minute },
          { zone: zone }
        );
        let hint = "";
        if (swapped.isValid && swapped > $now) {
          hint = "\n\nDid you mean " + swapped.toFormat("cccc d LLLL yyyy 'at' HH:mm") +
            "? That is the same numbers with the day and the month the other way round.";
        }
        scheduleError = {
          code: "schedule_in_past",
          param: "scheduled_time",
          message: "You asked for " + when.toFormat("cccc d LLLL yyyy 'at' HH:mm") +
            ", which has already passed.\nRight now it is " +
            $now.toFormat("cccc d LLLL yyyy 'at' HH:mm") + " in " + zone + "." + hint
        };
      } else {
        // Send a full ISO instant rather than a local string, so no interpretation of
        // the timezone is left to either side.
        scheduledTime = when.toISO();
        scheduleHuman = when.toFormat("cccc d LLLL yyyy 'at' HH:mm");
      }
    }
  }
}

const captionMap = {
  instagram: film.caption_instagram,
  tiktok: film.caption_tiktok,
  youtube: film.caption_youtube,
  facebook: film.caption_facebook,
  linkedin: film.caption_linkedin,
  x: film.caption_x,
  bluesky: film.caption_x,
  threads: film.caption_instagram,
  pinterest: film.caption_instagram,
  tumblr: film.caption_instagram,
  googlebusinessprofile: film.caption_facebook
};

// Strictest limit across everything being posted to, and the network that set it.
let limit = NO_LIMIT;
let strictest = matched[0];
for (const net of matched) {
  const cap = LIMITS[net] === undefined ? NO_LIMIT : LIMITS[net];
  if (cap < limit) { limit = cap; strictest = net; }
}

let caption = String(pick(form, "caption", "Caption")).trim();
if (!caption) { caption = captionMap[strictest] || film.caption_instagram || film.hook || ""; }

// If the operator caption will not fit, swap to the platform-native one the Copy
// Chief wrote for the strictest network before resorting to truncation.
if (caption.length > limit && captionMap[strictest]) {
  const native = String(captionMap[strictest]).trim();
  if (native.length <= limit) { caption = native; }
}

// Append the brand link only when there is room for it.
const link = String(film.brand_link || "").trim();
if (link && caption.length + link.length + 2 <= limit) {
  caption = caption + "\n\n" + link;
}

caption = fit(caption, limit);

const matchedLabels = [];
for (const net of matched) { matchedLabels.push(labelFor[net] || net); }

// ---- per-network publish options -------------------------------------------
// Postoria rejects the whole post if a youtube or tiktok option block arrives
// without an account of that network in the same post. The Postoria node omits an
// option block whose fields are all empty, so emitting "" here is exactly what keeps
// the block off the request when the network was not selected.
const hasYouTube = matched.indexOf("youtube") !== -1;
const hasTikTok = matched.indexOf("tiktok") !== -1;

// YouTube will not publish a video with no title, caps it at 100 characters, and
// rejects angle brackets outright.
let youtubeTitle = "";
if (hasYouTube) {
  const rawTitle = String(
    pick(form, "youtube_title", "YouTube title") || film.youtube_title || film.campaign_name || ""
  ).replace(/[<>]/g, " ").replace(/\s+/g, " ").trim();
  if (!rawTitle) {
    throw new Error("YouTube is selected but there is no title to publish with. " +
      "Fill in the YouTube title field on the Distribution Console and send it again.");
  }
  youtubeTitle = fit(rawTitle, 100);
}

// Tags travel to Postoria as a comma-separated list. The Copy Chief writes hashtags
// space separated with a leading #, so split on whitespace, drop the hash, and stay
// inside the 500-character tag budget YouTube allows.
let youtubeTags = "";
if (hasYouTube) {
  const parts = String(film.hashtags || "").replace(/#/g, " ").split(/[\s,]+/);
  const tags = [];
  let budget = 450;
  for (const part of parts) {
    const tag = part.trim();
    if (!tag || tags.length >= 15) { continue; }
    if (tag.length + 2 > budget) { break; }
    budget = budget - (tag.length + 2);
    tags.push(tag);
  }
  youtubeTags = tags.join(", ");
}

// TikTok will not accept a post with no privacy level. Public is the only sensible
// default for a campaign. An account that is not cleared to post publicly is the rare
// case, and Postoria reports that back on the post rather than failing silently.
const tiktokPrivacy = hasTikTok ? "public" : "";

const result = {
  session_id: film.session_id,
  chat_id: film.chat_id,
  campaign_name: film.campaign_name,
  media_kind: film.media_kind,
  media_url: film.media_url,
  asset_label: film.asset_label,
  film_url: film.media_url,
  media_id: String(mediaId),
  account_ids: accountIds,
  account_ids_csv: accountIds.join(","),
  networks: matchedLabels.join(", "),
  unconnected_networks: missing.join(", "),
  skipped_networks: skipped.join(", "),
  selected_all: wantsAll,
  publish_mode: publishMode,
  publish_mode_label: modeLabel,
  scheduled_time: scheduledTime,
  scheduled_time_human: scheduleHuman,
  timezone: zone,
  schedule_ok: scheduleError ? false : true,
  caption: caption,
  caption_length: caption.length,
  caption_limit: limit,
  caption_limited_by: strictest,
  first_comment: fit(pick(form, "first_comment", "First comment (hashtags)"), limit),
  youtube_selected: hasYouTube,
  tiktok_selected: hasTikTok,
  youtube_title: youtubeTitle,
  youtube_tags: youtubeTags,
  tiktok_privacy: tiktokPrivacy
};

// Shaped like a Postoria error so the existing failure lane handles it unchanged.
if (scheduleError) {
  result.error = {
    message: scheduleError.message,
    code: scheduleError.code,
    param: scheduleError.param
  };
}

return [{ json: result }];

} catch (err) {
  throw new Error(
    "Build Publish Plan failed: " + (err && err.message ? err.message : String(err)) +
    " — check the Distribution Console answers, especially the networks selected " +
    "and the schedule date/time.");
}

