parameters.jsCode:
// The preview must be delivered before the loop advances, so it sits inline rather
// than on a side branch. This re-emits the frame record so Loop Frames accumulates
// frame data and not the Telegram API response.
return [{ json: $("Frame Record").last().json }];

// Same inline-preview pattern as the first pass: deliver the revised still, then
// hand the frame record back to the loop.
return [{ json: $("Refined Frame Record").last().json }];

// Approved as-is. Emit an empty steer so Build Beat Plan reads the same shape on
// both the approve and the adjust path.
return [{ json: { visual_note: "", hook_override: "", steered: false } }];

// n8n keys form answers by field LABEL, not fieldName. pick() resolves either.
function pick(src, key, label) {
  const norm = function (s) { return String(s).toLowerCase().replace(/[^a-z0-9]/g, ""); };
  const map = {};
  for (const k of Object.keys(src)) { map[norm(k)] = src[k]; }
  const byKey = map[norm(key)];
  if (byKey !== undefined && byKey !== "") { return byKey; }
  const byLabel = map[norm(label)];
  if (byLabel !== undefined && byLabel !== "") { return byLabel; }
  return "";
}

const form = $input.first().json.data || {};
return [{
  json: {
    action: pick(form, "action", "What next") || "Apply my notes and build frames",
    visual_note: String(pick(form, "visual_note", "What should change in the visuals")).trim(),
    hook_override: String(pick(form, "hook_override", "New hook")).trim(),
    steered: true
  }
}];

// n8n keys form answers by field LABEL, not fieldName. pick() resolves either.
function pick(src, key, label) {
  const norm = function (s) { return String(s).toLowerCase().replace(/[^a-z0-9]/g, ""); };
  const map = {};
  for (const k of Object.keys(src)) { map[norm(k)] = src[k]; }
  const byKey = map[norm(key)];
  if (byKey !== undefined && byKey !== "") { return byKey; }
  const byLabel = map[norm(label)];
  if (byLabel !== undefined && byLabel !== "") { return byLabel; }
  return "";
}

const form = $input.first().json.data || {};
const action = pick(form, "action", "What next") || "Refine these frames";
const low = String(action).toLowerCase();

// One form, three outcomes: re-edit the frames, publish a still as it stands, or stop.
let nextAction = "refine";
if (low.indexOf("post") !== -1 || low.indexOf("still") !== -1) {
  nextAction = "still";
} else if (low.indexOf("cancel") !== -1) {
  nextAction = "cancel";
}

// "Beat 2" becomes 2. Anything unreadable falls back to the hero frame.
const frameChoice = String(pick(form, "still_frame", "Which frame to post") || "Beat 1");
const digits = frameChoice.match(/\d+/);
const stillBeat = digits ? Number(digits[0]) : 1;

return [{
  json: {
    action: action,
    next_action: nextAction,
    refine_notes: String(pick(form, "refine_notes", "What should change")).trim(),
    beat_focus: pick(form, "beat_focus", "Apply to") || "All beats",
    still_beat: stillBeat
  }
}];

// The session row and the brief acknowledgement must land before the studio runs,
// so they sit inline rather than on a side branch that n8n would queue to the end.
// This hands the production spec back to the merge that feeds the Creative Director.
return [{ json: $("Car OS Brief Compiler").first().json }];

// Pre-fill the brief from the photo caption, or from the most recent campaign for
// the same vehicle, so a repeat run starts from last time instead of from scratch.
const msg = $("Car OS Trigger").first().json.message || {};
const caption = String(msg.caption || msg.text || "").trim();
const prev = $input.first().json || {};
const recalled = !!(prev && prev.car_model);

const RATIO_LABEL = {
  "9:16": "9:16 Reels / TikTok / Shorts",
  "4:5": "4:5 Feed portrait",
  "1:1": "1:1 Feed square",
  "16:9": "16:9 YouTube / landscape"
};

// The Creative Brief message is rendered as Telegram Markdown, not HTML. Strip the
// control characters so a model name like GT_R cannot break the whole message.
function md(s) {
  return String(s || "").replace(/[*_`\[\]()~>#+=|{}.!-]/g, " ").replace(/\s+/g, " ").trim();
}

const model = md(recalled ? prev.car_model : caption);

let line;
if (recalled) {
  line = "I found a previous campaign for *" + model + "* and pre-filled those settings. Change anything you like.";
} else if (caption) {
  line = "Starting a fresh brief for *" + model + "*.";
} else {
  line = "New vehicle. Tip: add the model name as the photo caption next time and I will pre-fill it.";
}

return [{
  json: {
    suggested_model: (recalled ? prev.car_model : caption) || "",
    suggested_objective: (recalled && prev.objective) || "Transformation and Detailing Reveal",
    suggested_ratio: (recalled && RATIO_LABEL[prev.ratio]) || "9:16 Reels / TikTok / Shorts",
    suggested_film_length: (recalled && prev.film_length) || "Signature 3 beats 15s",
    suggested_tone: (recalled && prev.tone) || "Premium and Cinematic",
    recalled: recalled,
    recall_line: line
  }
}];

