// Postoria reports one validation param per response, so surface the exact one
// rather than a generic failure.
const e = ($input.first().json || {}).error || {};
return [{
  json: {
    error_message: e.message || "Postoria rejected the post.",
    error_code: e.code || "unknown",
    error_param: e.param || "",
    http_code: e.http_code || ""
  }
}];

// Single entry point into the distribution stack. Two producers feed it: the
// finished film from Resolve Film URL, and a still handed straight over from the
// frame review before anything was animated. Everything downstream reads this node,
// so the Postoria lane never has to know which one it got.

const bp = $("Set Campaign Blueprint").first().json;
const inp = $input.first().json || {};
const frameSet = $("Compile Frame Set").last().json;

// Only Resolve Film URL carries film_url, so its presence identifies the lane.
const isFilm = Boolean(inp.film_url);

let mediaUrl = "";
let mediaKind = "video";
let assetLabel = "";
let beatLabel = "";
let beatNo = 0;
let seconds = 0;
let cost = bp.est_cost_usd;

if (isFilm) {
  mediaUrl = inp.film_url;
  seconds = frameSet.total_seconds;
  assetLabel = seconds + "s film, " + frameSet.beats + " beat(s), " + bp.ratio;
} else {
  mediaKind = "image";
  const frames = frameSet.frames || [];
  const wanted = Number(inp.still_beat || 1);
  let chosen = null;
  for (const f of frames) {
    if (Number(f.beat) === wanted) { chosen = f; }
  }
  // A one-beat or two-beat campaign has no Beat 3, so fall back to the hero frame.
  if (!chosen) { chosen = frames[0]; }
  if (!chosen || !chosen.frame_url) {
    throw new Error("No rendered frame is available to publish.");
  }
  mediaUrl = chosen.frame_url;
  beatNo = Number(chosen.beat) || wanted;
  beatLabel = chosen.beat_label || ("Beat " + beatNo);
  assetLabel = "still from beat " + beatNo + ", " + beatLabel + ", " + bp.ratio;
  // Nothing was animated, so the run only ever paid for the frames. Unit price
  // comes from Car OS Config so it stays in step with the blueprint estimate.
  const priceFrame = Number($("Car OS Config").first().json.price_frame_usd) || 0.09;
  cost = Math.round(priceFrame * frameSet.beats * 10000) / 10000;
}

// Telegram panels are parsed as legacy Markdown, so anything rendered inside one
// needs its control characters stripped first.
function md(s) {
  return String(s == null ? "" : s).replace(/[*_`\[\]()]/g, " ").replace(/[ \t]+/g, " ").trim();
}

return [{
  json: {
    session_id: bp.session_id,
    chat_id: bp.chat_id,
    campaign_name: bp.campaign_name,
    campaign_name_md: bp.campaign_name_md || bp.campaign_name,
    hook: bp.hook,
    hook_md: bp.hook_md || bp.hook,
    ratio: bp.ratio,
    media_kind: mediaKind,
    media_url: mediaUrl,
    // Kept as an alias so the post log and the failure lane read one field for
    // whichever asset actually went out.
    film_url: mediaUrl,
    asset_label: assetLabel,
    asset_label_md: md(assetLabel),
    beat: beatNo,
    beat_label: beatLabel,
    beat_label_md: md(beatLabel),
    total_seconds: seconds,
    est_cost_usd: cost,
    caption_instagram: bp.caption_instagram,
    caption_tiktok: bp.caption_tiktok,
    caption_youtube: bp.caption_youtube,
    caption_facebook: bp.caption_facebook,
    caption_linkedin: bp.caption_linkedin,
    caption_x: bp.caption_x,
    youtube_title: bp.youtube_title,
    hashtags: bp.hashtags,
    first_comment: bp.first_comment,
    brand_link: bp.brand_link
  }
}];

// Postoria workspace auto-detection.
//
// workspace:getMany is the only Postoria operation that does not itself require a
// workspace ID, which makes it the one call that can bootstrap the rest of the lane.
// Resolving the ID here means a new operator supplies an API credential and nothing
// else: no ID to dig out of a dashboard URL, and no plain-text field left lying around
// for someone to paste a live API key into by mistake.
//
// SETUP. If this Postoria account has more than one workspace, put the name of the one
// Car OS publishes to on the line below, and the same name in Pick Ops Workspace. A
// name, not a number. With a single workspace on the account, leave it empty.
const PREFERRED_WORKSPACE = "";

function norm(s) {
  return String(s == null ? "" : s).toLowerCase().replace(/\s+/g, " ").trim();
}

const rows = [];
let apiError = "";

for (const item of $input.all()) {
  const w = item.json || {};
  if (w.error) {
    apiError = String(w.error.message || w.error);
    continue;
  }
  const id = w.id != null ? w.id : (w.workspace_id != null ? w.workspace_id : w.value);
  if (id == null) { continue; }
  const name = w.name != null ? w.name : (w.title != null ? w.title : String(id));
  rows.push({ id: String(id), name: String(name) });
}

const listed = [];
for (const r of rows) { listed.push(r.name + " (" + r.id + ")"); }

// Failing here is deliberate and cheap. Discovering the same problem after the film has
// rendered costs a full render, so this lane refuses to start rather than produce an
// asset it cannot publish.
if (!rows.length) {
  throw new Error(
    "Postoria returned no workspaces" + (apiError ? " (" + apiError + ")" : "") +
    ". Check that the Postoria credential is valid and that the API key has workspace access."
  );
}

let chosen = null;

if (PREFERRED_WORKSPACE) {
  for (const r of rows) {
    if (norm(r.name) === norm(PREFERRED_WORKSPACE)) { chosen = r; }
  }
  if (!chosen) {
    throw new Error(
      "No Postoria workspace is named \"" + PREFERRED_WORKSPACE + "\". This account has: " +
      listed.join(", ") + ". Correct PREFERRED_WORKSPACE in the Pick Workspace node, or " +
      "clear it if there is only one workspace."
    );
  }
} else if (rows.length === 1) {
  chosen = rows[0];
} else {
  // Never guess. Most Postoria accounts carry an unused "My Workspace" beside the real
  // one, API list order is not contractual, and publishing into the wrong workspace is
  // silent. One error at setup beats a campaign posted where nobody is looking.
  throw new Error(
    "This Postoria account has " + rows.length + " workspaces: " + listed.join(", ") +
    ". Open the Pick Workspace node and set PREFERRED_WORKSPACE to the name of the one " +
    "Car OS should publish to, then set the same name in Pick Ops Workspace."
  );
}

return [{
  json: {
    workspace_id: chosen.id,
    workspace_name: chosen.name,
    workspace_count: rows.length,
    workspaces_available: listed.join(", ")
  }
}];

// Same workspace bootstrap as the campaign lane. Keep PREFERRED_WORKSPACE identical in
// both nodes, otherwise the daily digest reports on a different workspace than the one
// Car OS publishes to.
const PREFERRED_WORKSPACE = "";

